18	// CommittedReader provides read access to committed checkpoint data.
19	// Both GitStore (v1) and V2GitStore (v2) implement this interface.
20	type CommittedReader interface {
21		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
22		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
23	}
