25	// CommittedListReader provides read and list access to committed checkpoint data.
26	// GitStore, V2GitStore, and DualCheckpointReader implement this interface.
27	type CommittedListReader interface {
28		CommittedReader
29		ListCommitted(ctx context.Context) ([]CommittedInfo, error)
30		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error)
31		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
32		ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error)
33	}
