35	// CommittedStore provides read/list access plus committed checkpoint metadata updates.
36	// NewCommittedReader returns this abstraction so callers do not need to know which
37	// backing checkpoint format was selected.
38	type CommittedStore interface {
39		CommittedListReader
40		UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error
41		GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error)
42	}
