44	type committedReadMode int
45	
46	const (
47		committedReadV1 committedReadMode = iota
48		committedReadDual
49		committedReadV2
50	)
51	
52	// CommittedReaderOptions configures NewCommittedReader.
53	type CommittedReaderOptions struct {
54		BlobFetcher BlobFetchFunc
55	}
56	
57	//nolint:ireturn // Factory selects among v1, v2, and dual store implementations.
58	func NewCommittedReader(ctx context.Context, repo *git.Repository, opts CommittedReaderOptions) (CommittedStore, error) {
59		if repo == nil {
60			return nil, errors.New("git repository is required")
61		}
62	
63		v1Store := NewGitStore(repo)
64		if opts.BlobFetcher != nil {
65			v1Store.SetBlobFetcher(opts.BlobFetcher)
66		}
67	
68		mode := resolveCommittedReadMode(
69			settings.IsCheckpointsV2Enabled(ctx),
70			settings.CheckpointsVersion(ctx),
71			hasLocalV2MainRef(repo),
72		)
73	
74		var v2Store *V2GitStore
75		if mode != committedReadV1 {
76			v2Store = NewV2GitStore(repo)
77			if opts.BlobFetcher != nil {
78				v2Store.SetBlobFetcher(opts.BlobFetcher)
79			}
80		}
81	
82		switch mode {
83		case committedReadV2:
84			return v2Store, nil
85		case committedReadDual:
86			return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
87		case committedReadV1:
88			return v1Store, nil
89		default:
90			return nil, fmt.Errorf("unknown committed checkpoint read mode: %d", mode)
91		}
92	}
93	
94	func resolveCommittedReadMode(checkpointsV2Enabled bool, checkpointsVersion int, localV2MainRef bool) committedReadMode {
95		if checkpointsVersion == 2 {
96			return committedReadV2
97		}
98		if checkpointsV2Enabled || localV2MainRef {
99			return committedReadDual
100		}
101		return committedReadV1
102	}
