117	func (r *DualCheckpointReader) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
118		summary, err := r.v2.ReadCommitted(ctx, checkpointID)
119		if err == nil && summary != nil {
120			return summary, nil
121		}
122		if ctxErr := ctx.Err(); ctxErr != nil {
123			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
124		}
125		if err != nil {
126			logV2Fallback(ctx, "v2 ReadCommitted failed, falling back to v1", checkpointID, err)
127		}
128		return r.v1.ReadCommitted(ctx, checkpointID)
129	}
