131	func (r *DualCheckpointReader) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
132		content, err := r.v2.ReadSessionContent(ctx, checkpointID, sessionIndex)
133		if err == nil {
134			return content, nil
135		}
136		if ctxErr := ctx.Err(); ctxErr != nil {
137			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
138		}
139		if errors.Is(err, ErrCheckpointNotFound) {
140			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
141			if existsErr != nil {
142				return nil, existsErr
143			}
144			if v2CheckpointExists {
145				summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
146				if summaryErr != nil {
147					return nil, summaryErr
148				}
149				if !hasSingleV1FallbackSession(summary, sessionIndex) {
150					return nil, err
151				}
152				return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
153			}
154			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
155		}
156		sessionID, sessionIDErr := r.v2SessionID(ctx, checkpointID, sessionIndex)
157		if sessionIDErr != nil {
158			if ctxErr := ctx.Err(); ctxErr != nil {
159				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
160			}
161			originalErr := fallbackReadError(err, "read v2 session metadata for v1 fallback", sessionIDErr)
162			summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, originalErr)
163			if summaryErr != nil {
164				return nil, summaryErr
165			}
166			if !hasSingleV1FallbackSession(summary, sessionIndex) {
167				return nil, originalErr
168			}
169			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, originalErr)
170		}
171		return r.readV1SessionContentByID(ctx, checkpointID, sessionID, err)
172	}
