174	func (r *DualCheckpointReader) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error) {
175		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
176		if err == nil {
177			return metadata, nil
178		}
179		if ctxErr := ctx.Err(); ctxErr != nil {
180			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
181		}
182		if errors.Is(err, ErrCheckpointNotFound) {
183			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
184			if existsErr != nil {
185				return nil, existsErr
186			}
187			if v2CheckpointExists {
188				summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
189				if summaryErr != nil {
190					return nil, summaryErr
191				}
192				if !hasSingleV1FallbackSession(summary, sessionIndex) {
193					return nil, err
194				}
195				return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
196			}
197			return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
198		}
199		summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
200		if summaryErr != nil {
201			return nil, summaryErr
202		}
203		if !hasSingleV1FallbackSession(summary, sessionIndex) {
204			return nil, err
