209	func (r *DualCheckpointReader) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
210		content, err := r.v2.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
211		if err == nil {
212			return content, nil
213		}
214		if ctxErr := ctx.Err(); ctxErr != nil {
215			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
216		}
217		if errors.Is(err, ErrCheckpointNotFound) {
218			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
219			if existsErr != nil {
