222			if v2CheckpointExists {
223				return nil, err
224			}
225			return r.readV1SessionMetadataAndPromptsByIndex(ctx, checkpointID, sessionIndex, err)
226		}
227		sessionID, sessionIDErr := r.v2SessionID(ctx, checkpointID, sessionIndex)
228		if sessionIDErr != nil {
