276	func (r *DualCheckpointReader) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
277		v2Committed, v2Err := r.v2.ListCommitted(ctx)
278		v1Committed, v1Err := r.v1.ListCommitted(ctx)
279	
280		if v2Err != nil {
281			logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
282				slog.String("error", v2Err.Error()),
283			)
284			if v1Err != nil {
285				return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
286			}
287			return v1Committed, nil
288		}
289	
290		if v1Err != nil {
291			logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
292				slog.String("error", v1Err.Error()),
293			)
294			return v2Committed, nil
295		}
296	
297		seen := make(map[id.CheckpointID]struct{}, len(v2Committed))
298		for _, c := range v2Committed {
299			seen[c.CheckpointID] = struct{}{}
300		}
301		committed := make([]CommittedInfo, 0, len(v2Committed)+len(v1Committed))
302		committed = append(committed, v2Committed...)
303		for _, c := range v1Committed {
304			if _, ok := seen[c.CheckpointID]; !ok {
305				committed = append(committed, c)
306			}
307		}
308		return committed, nil
309	}
