404	func (r *DualCheckpointReader) readV1SessionMetadataAndPromptsByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string, originalErr error) (*SessionContent, error) {
405		summary, err := r.readV1FallbackSummary(ctx, checkpointID, originalErr)
406		if err != nil {
407			return nil, err
408		}
409		if summary == nil {
410			return nil, originalErr
411		}
412		for i := range len(summary.Sessions) {
413			content, readErr := r.v1.ReadSessionMetadataAndPrompts(ctx, checkpointID, i)
414			if readErr != nil {
415				continue
416			}
417			if content != nil && content.Metadata.SessionID == sessionID {
418				return content, nil
419			}
420		}
421		return nil, fallbackReadError(originalErr, "read v1 fallback session metadata and prompts", fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID))
422	}
