424	func (r *DualCheckpointReader) readV1SessionMetadataAndPromptsByIndex(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, originalErr error) (*SessionContent, error) {
425		content, err := r.v1.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
426		if err == nil {
427			return content, nil
428		}
429		if ctxErr := ctx.Err(); ctxErr != nil {
430			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
431		}
432		return nil, fallbackReadError(originalErr, "read v1 session metadata and prompts", err)
433	}
434	
435	func (r *DualCheckpointReader) readV1FallbackSummary(ctx context.Context, checkpointID id.CheckpointID, originalErr error) (*CheckpointSummary, error) {
436		summary, err := r.v1.ReadCommitted(ctx, checkpointID)
437		if err == nil {
438			return summary, nil
439		}
440		if ctxErr := ctx.Err(); ctxErr != nil {
441			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
442		}
443		return nil, fallbackReadError(originalErr, "read v1 checkpoint summary", err)
444	}
445	
446	func hasSingleV1FallbackSession(summary *CheckpointSummary, sessionIndex int) bool {
447		return summary != nil && len(summary.Sessions) == 1 && sessionIndex == 0
448	}
449	
450	func fallbackReadError(primaryErr error, fallbackOperation string, fallbackErr error) error {
451		if fallbackErr == nil {
452			return primaryErr
453		}
454		return errors.Join(primaryErr, fmt.Errorf("%s: %w", fallbackOperation, fallbackErr))
455	}
456	
457	func logV2Fallback(ctx context.Context, message string, checkpointID id.CheckpointID, err error) {
458		if errors.Is(err, ErrCheckpointNotFound) || errors.Is(err, ErrNoTranscript) {
459			return
460		}
461		logging.Debug(ctx, message,
462			slog.String("checkpoint_id", checkpointID.String()),
463			slog.String("error", err.Error()),
464		)
465	}
466	
467	// ReadCommittedCheckpoint reads a committed checkpoint summary and normalizes
468	// a nil store response into ErrCheckpointNotFound.
469	func ReadCommittedCheckpoint(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
470		if err := ctx.Err(); err != nil {
471			return nil, err //nolint:wrapcheck // Propagating context cancellation
472		}
473	
474		summary, err := reader.ReadCommitted(ctx, checkpointID)
475		if err != nil {
476			return nil, fmt.Errorf("read committed checkpoint: %w", err)
477		}
478		if summary == nil {
479			return nil, ErrCheckpointNotFound
480		}
481		return summary, nil
482	}
483	
484	// ReadLatestSessionContent reads the latest session from an already-resolved
485	// committed reader and summary.
486	func ReadLatestSessionContent(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
487		if summary == nil || len(summary.Sessions) == 0 {
488			return nil, ErrCheckpointNotFound
489		}
490		latestIndex := len(summary.Sessions) - 1
491		content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
492		if err != nil {
493			return nil, fmt.Errorf("read session %d content: %w", latestIndex, err)
494		}
